//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<!--root--><body><noscript id=host>held</noscript><button id=button><noscript id=guard>guarded</noscript></button><select id=loadedchoice><optgroup disabled><option value=a>A<hr><option value=b selected>B</select><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://noscript-text-ranges.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}




fn by_id(d:&Document,id:&str)->usize{d.nodes.iter().enumerate().find(|(n,_)|d.attr(*n,"id")==Some(id)).unwrap().0}
#[test]
fn range_fragment_controls_detached_defaults_identity_and_connection(){
 let(mut d,mut f,mut p)=fixture();let count=f.controls.len();run(&mut d,&mut f,&mut p,r#"
var r=document.createRange(),out=document.getElementById('out'),watch=new MutationObserver(function(){});r.selectNodeContents(out);watch.observe(out,{childList:true});var fragment=r.createContextualFragment('<input id=ftext value=Initial><input id=fcheck type=checkbox checked><textarea id=farea>First&amp;line</textarea><select id=fchoice><optgroup label=Disabled disabled><option value=a>A</optgroup><option value=b selected>B</select>'),text=fragment.childNodes[0],check=fragment.childNodes[1],area=fragment.childNodes[2],choice=fragment.childNodes[3];
if(fragment.childNodes.length!==4||text.value!=='Initial'||!check.checked||area.value!=='First&line'||choice.value!=='b'||choice.selectedIndex!==1||text.ownerDocument!==document||area.ownerDocument!==document||text.parentNode!==fragment||text.isConnected||choice.isConnected||document.getElementById('ftext')!==null||watch.takeRecords().length||out.textContent!=='Real'||r.endOffset!==1)throw 'detached native control defaults';text.value='edited';check.checked=false;area.value='edited area';choice.value='a';if(out.appendChild(fragment)!==fragment||fragment.firstChild!==null||document.getElementById('ftext')!==text||!text.isConnected||text.value!=='edited'||check.checked||area.value!=='edited area'||choice.value!=='a')throw 'native control identity and edited state on connection';var rs=watch.takeRecords();if(rs.length!==1||rs[0].addedNodes.length!==4||rs[0].addedNodes[0]!==text||rs[0].addedNodes[3]!==choice)throw 'actual native control publication';
"#);assert_eq!(f.controls.len(),count+4);let text=by_id(&d,"ftext");let area=by_id(&d,"farea");let check=by_id(&d,"fcheck");let choice=by_id(&d,"fchoice");assert_eq!(f.controls[&text].kind,Kind::Text);assert_eq!(f.controls[&text].value.text(),"edited");assert_eq!(f.controls[&area].kind,Kind::TextArea);assert_eq!(f.controls[&area].value.text(),"edited area");assert_eq!(f.controls[&check].kind,Kind::Checkbox);assert!(!f.controls[&check].checked);let select=f.controls[&choice].select.as_ref().unwrap();assert_eq!(select.options.len(),2);assert!(select.options[0].disabled);assert!(!select.options[1].disabled);assert_eq!(select.options[1].group,None);assert_eq!(select.selected,Some(0));assert!(p.take_dynamic_scripts().is_empty());
}
#[test]
fn range_fragment_controls_select_hr_has_real_native_group_state(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var loaded=document.getElementById('loadedchoice'),holder=document.createElement('div');document.body.appendChild(holder);holder.appendChild(loaded);if(loaded.parentNode!==holder||loaded.children.length!==3||loaded.value!=='b'||loaded.selectedIndex!==1)throw 'loaded native SELECT HR whole movement';var r=document.createRange();r.selectNodeContents(document.getElementById('out'));var fragment=r.createContextualFragment('<select id=hrchoice><optgroup id=hrgroup disabled><option value=a>A<hr id=hrline><option id=hrsecond value=b selected>B</select>'),choice=fragment.firstChild;if(choice.children.length!==3||choice.children[1].localName!=='hr'||choice.children[2].localName!=='option'||choice.value!=='b'||choice.selectedIndex!==1)throw 'actual parsed HR select';document.getElementById('out').appendChild(fragment);if(choice!==document.getElementById('hrchoice'))throw 'same native SELECT';
"#);let state=f.controls[&by_id(&d,"hrchoice")].select.as_ref().unwrap();assert_eq!(state.options.len(),2);assert!(state.options[0].disabled);assert_eq!(state.options[1].group,None);assert!(!state.options[1].disabled);assert_eq!(state.selected,Some(1));assert_eq!(state.rows.len(),3);
}
#[test]
fn range_fragment_controls_import_select_hr_shared_planner(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var source=new DOMParser().parseFromString('<select id=importchoice><optgroup disabled><option value=a>A<hr><option value=b selected>B</select>','text/html'),original=source.getElementById('importchoice'),copy=document.importNode(original,true);if(copy===original||copy.ownerDocument!==document||original.ownerDocument!==source||copy.children.length!==3||copy.value!=='b'||copy.selectedIndex!==1)throw 'shared native import control state';document.getElementById('out').appendChild(copy);
"#);let state=f.controls[&by_id(&d,"importchoice")].select.as_ref().unwrap();assert_eq!(state.options.len(),2);assert!(state.options[0].disabled);assert!(!state.options[1].disabled);assert_eq!(state.options[1].group,None);assert_eq!(state.selected,Some(1));
}
#[test]
fn range_fragment_controls_initial_refusal_no_native_or_dom_prefix_and_recovery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var r=document.createRange(),out=document.getElementById('out'),watch=new MutationObserver(function(){});r.selectNodeContents(out);watch.observe(out,{childList:true});");let before=format!("{:?}",d.nodes);let controls=f.controls.len();let commits=p.state.dom_commits;
 for code in ["r.createContextualFragment('<input value=good><button>bad</button>');","r.createContextualFragment('<input value=good><input type=file>');","r.createContextualFragment('<input value=good><input form=missing>');","r.createContextualFragment('<textarea>good</textarea><img src=missing>');","r.createContextualFragment('<select><option onclick=bad>X</select>');"]{p.begin_job();let e=refusal(&mut d,&mut f,&mut p,code);assert!(!e.is_empty());assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls.len(),controls);assert_eq!(p.state.dom_commits,commits);}
 let retained=p.state.retained_limit;let nodes=p.state.node_limit;
 for mode in 0..4{p.begin_job();match mode{0=>p.state.copy_work=0,1=>p.state.host_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.node_limit=d.nodes.len()};let e=refusal(&mut d,&mut f,&mut p,"r.createContextualFragment('<input value=seed><textarea>seed</textarea><select><option>X</select>');").to_ascii_lowercase();assert!(e.contains("limit")||e.contains("allowance")||e.contains("storage"),"{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(f.controls.len(),controls);assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=retained;p.state.node_limit=nodes;}
 p.begin_job();run(&mut d,&mut f,&mut p,"if(watch.takeRecords().length||out.textContent!=='Real'||r.startContainer!==out||r.endOffset!==1)throw 'no failed control prefix';var fresh=r.createContextualFragment('<input value=fresh>');if(fresh.firstChild.value!=='fresh'||fresh.firstChild.ownerDocument!==document||fresh.firstChild.isConnected)throw 'native control recovery';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
